(6875557, 1035183, 153152, '<td valign="top">I like the overall affect, and original thought. Well composed. I can''t put it into words, but I feel that something is lacking to make this photo really stand out, like others in this challenge.</td>', 'I like the overall affect, and original thought. Well composed. I can''t put it into words, but I feel that something is lacking to make this photo really stand out, like others in this challenge.', '2012-10-04 13:18:26.000000', NULL, 1),
(6875558, 1035182, 153152, '<td valign="top">There is a lack of detail, or anything to draw me into this photo.</td>', 'There is a lack of detail, or anything to draw me into this photo.', '2012-10-04 13:19:44.000000', NULL, 1),
(6875559, 1035268, 153152, '<td valign="top">I really like this photo. The depth of field, and angle of the picture, plus composition makes this a picture that is hard to take the eyes off of.</td>', 'I really like this photo. The depth of field, and angle of the picture, plus composition makes this a picture that is hard to take the eyes off of.', '2012-10-04 13:21:39.000000', NULL, 1),
(6875560, 1035198, 83845, '<td valign="top">I think face is beautifully lit.  As much as I adore negative space, I think I would have cropped this a little tighter to bring more attent to the face.</td>', 'I think face is beautifully lit.  As much as I adore negative space, I think I would have cropped this a little tighter to bring more attent to the face.', '2012-10-04 13:23:29.000000', NULL, 1),
(6875562, 1034764, 153152, '<td valign="top">I may be wrong, but the light the man is holding looks more like a flashlight than a candle. Also, the brightness of the light makes it hard to actually see the man. I realize that is the point, but I think you may have gone to far.</td>', 'I may be wrong, but the light the man is holding looks more like a flashlight than a candle. Also, the brightness of the light makes it hard to actually see the man. I realize that is the point, but I think you may have gone to far.', '2012-10-04 13:23:56.000000', NULL, 1),
(6875564, 1035273, 153152, '<td valign="top">I like the balance of lighting, with the dark background.</td>', 'I like the balance of lighting, with the dark background.', '2012-10-04 13:26:57.000000', NULL, 1),
(6875565, 1034810, 83845, '<td valign="top">I love the colors you''ve brought out.</td>', 'I love the colors you''ve brought out.', '2012-10-04 13:27:08.000000', NULL, 1),
