(6875567, 1035241, 153152, '<td valign="top">This is a snapshot that was entered into a challenge that required some thought. The noise in this photo is very distracting to me.</td>', 'This is a snapshot that was entered into a challenge that required some thought. The noise in this photo is very distracting to me.', '2012-10-04 13:28:51.000000', NULL, 1),
(6875569, 1035234, 153152, '<td valign="top">Interesting black &amp; white. I like the touch of hair in front of the mask.</td>', 'Interesting black & white. I like the touch of hair in front of the mask.', '2012-10-04 13:30:34.000000', NULL, 1),
