(6875571, 1035107, 153152, '<td valign="top">This is a very thought provoking picture. I really like the composition and the burning of the pages to create primary light. Also the balance if light from the front right to the back left is nice and pleasing</td>', 'This is a very thought provoking picture. I really like the composition and the burning of the pages to create primary light. Also the balance if light from the front right to the back left is nice and pleasing', '2012-10-04 13:33:04.000000', NULL, 1),
(6875572, 1035259, 83845, '<td valign="top">Well done!</td>', 'Well done!', '2012-10-04 13:34:04.000000', NULL, 1),
(6875574, 1034520, 153152, '<td valign="top">A very interesting idea. I like how the evidently long exposure created the overall warm color to it.</td>', 'A very interesting idea. I like how the evidently long exposure created the overall warm color to it.', '2012-10-04 13:36:01.000000', NULL, 1),
(6875575, 1035200, 153152, '<td valign="top">I think you would have had a better photo by somehow composing the rose closer to the candle. I like it much better if I "crop" out the candle and look just at the flower.</td>', 'I think you would have had a better photo by somehow composing the rose closer to the candle. I like it much better if I "crop" out the candle and look just at the flower.', '2012-10-04 13:40:09.000000', NULL, 1),
(6875576, 1035265, 153152, '<td valign="top">I really like this. You captured the red dot in great focus and exposure. You also composed your photo in a pleasing way.</td>', 'I really like this. You captured the red dot in great focus and exposure. You also composed your photo in a pleasing way.', '2012-10-04 13:41:57.000000', NULL, 1),
(6875579, 1035177, 83845, '<td valign="top">Very edgy and artistic.  I love the colors...</td>', 'Very edgy and artistic.  I love the colors...', '2012-10-04 13:43:47.000000', NULL, 1),
(6875580, 1035268, 83845, '<td valign="top">The light hitting the red cloth is to die for!  Fingerprint is driving me crazy.</td>', 'The light hitting the red cloth is to die for!  Fingerprint is driving me crazy.', '2012-10-04 13:46:02.000000', NULL, 1),
(6875581, 1035263, 153152, '<td valign="top">This is one of my favorite photo''s of this challenge. The young lady stretched across the stair case, and not curled up, brings out the elegance of the dress and draws you to her face.</td>', 'This is one of my favorite photo''s of this challenge. The young lady stretched across the stair case, and not curled up, brings out the elegance of the dress and draws you to her face.', '2012-10-04 13:46:24.000000', NULL, 1),
