(6875590, 1035264, 153152, '<td valign="top">I am new to dpchallange, but I don''t see any use of composition except what the set creates. Their isn''t anything that draws me into the picture and causes me to focus my eyes on a main subject.</td>', 'I am new to dpchallange, but I don''t see any use of composition except what the set creates. Their isn''t anything that draws me into the picture and causes me to focus my eyes on a main subject.', '2012-10-04 13:51:32.000000', NULL, 1),
(6875591, 1035049, 100831, '<td valign="top">well executed story. kudos.</td>', 'well executed story. kudos.', '2012-10-04 13:51:48.000000', NULL, 1),
(6875592, 1035233, 100831, '<td valign="top">Ah, love the shadow.. wish you had turned the candles on.</td>', 'Ah, love the shadow.. wish you had turned the candles on.', '2012-10-04 13:52:17.000000', NULL, 1),
