(6875595, 1035272, 153152, '<td valign="top">I like the composition and the subject. The central apple then leads my eyes to the item that "isn''t like the others."</td>', 'I like the composition and the subject. The central apple then leads my eyes to the item that "isn''t like the others."', '2012-10-04 13:54:41.000000', NULL, 1),
(6875597, 1035236, 100831, '<td valign="top">This is like reading a good mystery - the light adds just enough information to make it interesting. The warmth gives a glow. Perfect composition.</td>', 'This is like reading a good mystery - the light adds just enough information to make it interesting. The warmth gives a glow. Perfect composition.', '2012-10-04 13:55:50.000000', NULL, 1),
