(6875599, 1035240, 100831, '<td valign="top">it glows.</td>', 'it glows.', '2012-10-04 13:57:25.000000', NULL, 1),
(6875600, 1035249, 153152, '<td valign="top">I enjoy looking at this photo. The sharp focus of the front candle holder, and then how the image spreads out, and back light by the slightly out of focus candles, plus overall composition, makes this an excellent photo.</td>', 'I enjoy looking at this photo. The sharp focus of the front candle holder, and then how the image spreads out, and back light by the slightly out of focus candles, plus overall composition, makes this an excellent photo.', '2012-10-04 13:57:57.000000', NULL, 1),
