(6875604, 1035195, 83845, '<td valign="top">Ah, coulda used some of that last night!</td>', 'Ah, coulda used some of that last night!', '2012-10-04 14:02:11.000000', NULL, 1),
(6875606, 1035183, 83845, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2012-10-04 14:03:03.000000', NULL, 1),
(6875608, 1035210, 153152, '<td valign="top">The sharp shadow on the siding of the building is quite distracting from the rest of the image.</td>', 'The sharp shadow on the siding of the building is quite distracting from the rest of the image.', '2012-10-04 14:03:13.000000', NULL, 1),
(6875610, 1035225, 153152, '<td valign="top">Interesting shot, but I can''t seem to come up with much else to say. There isn''t one place of focus, or interest. I just see for objects without much contrast.</td>', 'Interesting shot, but I can''t seem to come up with much else to say. There isn''t one place of focus, or interest. I just see for objects without much contrast.', '2012-10-04 14:06:13.000000', NULL, 1),
(6875611, 1035195, 153152, '<td valign="top">I believe this may have been a better photo if you had tried to compose it a little differently. Maybe you could have tried slightly tilting the bottles into the light and setting the candles a little further away. This may have given the bottles a little more even lighting, which I would have liked better.</td>', 'I believe this may have been a better photo if you had tried to compose it a little differently. Maybe you could have tried slightly tilting the bottles into the light and setting the candles a little further away. This may have given the bottles a little more even lighting, which I would have liked better.', '2012-10-04 14:08:30.000000', NULL, 1),
(6875613, 1035240, 153152, '<td valign="top">This is a great picture with much detail. I am concerned that this may have taken more than basic editing to bring out the detail you have in areas that are in darker corners.</td>', 'This is a great picture with much detail. I am concerned that this may have taken more than basic editing to bring out the detail you have in areas that are in darker corners.', '2012-10-04 14:11:49.000000', NULL, 1),
(6875615, 1035233, 153152, '<td valign="top">The white balance of this picture leads me to believe that the light source was not candlelight. I do like the composition, and the white underlay, but will score lowly in that I can''t tell the source of light.</td>', 'The white balance of this picture leads me to believe that the light source was not candlelight. I do like the composition, and the white underlay, but will score lowly in that I can''t tell the source of light.', '2012-10-04 14:13:46.000000', NULL, 1),
(6875684, 1035209, 113278, '<td valign="top">I sure do hope to see this at the top. Great work. Love the motion of the light.</td>', 'I sure do hope to see this at the top. Great work. Love the motion of the light.', '2012-10-04 15:25:22.000000', NULL, 1),
